614	export function receiptHandoff(
615	  record,
616	  { handoffId, executorId, sessionId, currentProblem = null } = {},
617	) {
618	  if (
619	    !ID.test(executorId) ||
620	    !ID.test(sessionId) ||
621	    /^(?:client|pending|unknown|timeout)/i.test(sessionId)
622	  )
623	    throw new Error("invalid receipt arguments");
624	  validateCurrentProblem(currentProblem);
625	  validateRecord(record);
626	  const next = structuredClone(record);
627	  if (
628	    next.handoff_id !== handoffId ||
629	    !next.rollover.claim ||
630	    next.rollover.claim.executor_id !== executorId
631	  )
632	    return { record: next, result: { decision: "STOP_DUPLICATE_OR_STALE" }, changed: false };
633	  if (currentProblem) return { record: next, result: { decision: currentProblem }, changed: false };
634	  if (next.rollover.receipt) {
635	    const result =
636	      next.rollover.receipt.executor_id === executorId &&
637	      next.rollover.receipt.session_id === sessionId
638	        ? { decision: "RECEIPT_RECORDED", idempotent: true }
639	        : { decision: "STOP_DUPLICATE_OR_STALE" };
640	    return { record: next, result, changed: false };
641	  }
642	  next.status = "receipted";
643	  next.rollover.receipt = { executor_id: executorId, session_id: sessionId };
644	  next.task.used_rollovers += 1;
645	  return {
646	    record: next,
647	    result: { decision: "RECEIPT_RECORDED", idempotent: false },
648	    changed: true,
649	  };
260	function receipt() {
261	  const stateValue = option("--state");
262	  const handoffId = option("--handoff-id");
263	  const executorId = option("--executor-id");
264	  const sessionId = option("--session-id");
265	  if (
266	    args.length ||
267	    !ID.test(executorId) ||
268	    !ID.test(sessionId) ||
269	    /^(?:client|pending|unknown|timeout)/i.test(sessionId)
270	  )
271	    throw new Error("invalid receipt arguments");
272	  const location = stateLocation(stateValue);
273	  return withLock(location.statePath, () => {
274	    const record = validateRecord(readJson(location.statePath));
275	    const currentProblem =
276	      record.handoff_id === handoffId && record.rollover.claim?.executor_id === executorId
277	        ? checkCurrent(record, location)
278	        : null;
279	    const transition = receiptHandoff(record, { handoffId, executorId, sessionId, currentProblem });
280	    if (transition.changed) atomicWrite(location.statePath, transition.record);
281	    if (transition.result.decision === "RECEIPT_RECORDED")
282	      return {
283	        ...transition.result,
284	        resume_prompt: receiptPrompt(transition.record, location),
285	        notice: LOCAL_CHECKS_NOTICE,
286	      };
287	    return transition.result;
288	  });
